head.script:

	scwin.onpageload = function() {
        idx = 10;
		//windowContainer1.createWindow( "title1" , null , "/hyundai/gridView_excelUpload.xml" , "windowTitle1" , "windowId1" , "" , "closeAction");
		//windowContainer1.createWindow( "title1" , null , "/hyundai/tabControl_hd.xml" , "windowTitle1" , "windowId1" , "" , "closeAction");
        var xmlArr = [
            "wincon_child.xml", 
            "selectbox_autoComplete_checkcombobox.xml",
            "checkcombobox_hd_bak.xml",
            "checkcombobox_hd.xml",
            "gridView_advancedExcelDown.xml",
            "gridView_autoComplete_radio.xml",
            "gridView_checkcombobox_manydata.xml",
            "gridView_checkcombobox.xml"
        ];
        var i = 0;
        var options = {
            title: (i+1)+"_"+(i+1),
            iconUrl: null,
            src: "window001.xml",
            windowTitle: "windowTitle"+(i+1),
            windowId: "windowId"+(i+1),
            frameMode:"wframe",
        };
        windowContainer1.createWindow( options );

        WebSquare.wUnit.getDomById('trigger1').click();
        WebSquare.wUnit.getDomById('trigger1').click();
        WebSquare.wUnit.getDomById('trigger1').click();

        windowContainer2.createWindow( options );

        WebSquare.wUnit.getDomById('trigger2').click();
        WebSquare.wUnit.getDomById('trigger2').click();
        WebSquare.wUnit.getDomById('trigger2').click();
	};

	scwin.onpageunload = function() {

	};

    scwin.trigger1_onclick = function() {
        var i = idx++;
        var options = {
            title: (i+1)+"_"+(i+1),
            iconUrl: null,
            src: "wincon_child.xml",
            windowTitle: "windowTitle"+(i+1),
            windowId: "windowId"+(i+1),
            frameMode:"wframe",
        };
        windowContainer1.createWindow( options );
    };

    scwin.trigger2_onclick = function() {
        var i = idx++;
        var options = {
            title: (i+1)+"_"+(i+1),
            iconUrl: null,
            src: "wincon_child.xml",
            windowTitle: "windowTitle"+(i+1),
            windowId: "windowId"+(i+1),
            frameMode:"wframe",
        };
        windowContainer2.createWindow( options );
    };
	scwin.onrestorebtnclick = function() {
        //console.log("user function onrestorebtnclick event");
    }
    scwin.onwindowchange = function() {
        console.log("onwindowchange");
    }


	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate = function() {
		scwin.simulateWrapper('#windowContainer1_subWindow3_header', 'drag-n-drop', {
			dx: 300,
			dy: 0
		});
	}

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getJq('#windowContainer1_subWindow3').offset().left > 30;
	}

	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('windowContainer1_subWindow3_restore').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('windowContainer1_subWindow3_header').click()");
		WebSquare.wUnit.addCommand("pause", "400");		
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
